-- Authorization simulation. All temporary identities, companies, profiles and logs roll back.
BEGIN;
CREATE TEMP TABLE assistant_checks(test text,passed boolean);
DO $qa$
DECLARE own uuid; sid uuid:=gen_random_uuid(); req uuid:=gen_random_uuid(); cid bigint; bid integer; name text:='اختبار المساعد '||left(gen_random_uuid()::text,8); answer jsonb; same jsonb; ctx jsonb; item jsonb; e public.dlv_profiles; ecid bigint;
BEGIN
 SELECT user_id INTO STRICT own FROM public.dlv_profiles WHERE active AND role='admin' AND workflow_role='admin';
 INSERT INTO auth.sessions(id,user_id,created_at,updated_at) VALUES(sid,own,now(),now());
 PERFORM set_config('request.jwt.claim.sub',own::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',own,'session_id',sid,'exp',extract(epoch from now()+interval '1 hour')::bigint,'aal','aal1')::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 BEGIN PERFORM public.dlv_owner_assistant_context();RAISE EXCEPTION 'Locked owner read context';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.dlv_owner_assistant_execute(req,'create_company',null,null,null,jsonb_build_object('name',name));RAISE EXCEPTION 'Locked owner executed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
 INSERT INTO public.dlv_owner_page_unlocks(user_id,session_id,expires_at) VALUES(own,sid::text,now()+interval '15 minutes');
 EXECUTE 'SET LOCAL ROLE authenticated';
 BEGIN PERFORM public.dlv_owner_assistant_execute(req,'arbitrary_sql',null,null,null,'{}');RAISE EXCEPTION 'Unknown action accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.dlv_owner_assistant_execute(req,'create_company',null,null,null,jsonb_build_object('name',name,'logo_url','https://invalid.example/a.png'));RAISE EXCEPTION 'Untrusted logo accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 answer:=public.dlv_owner_assistant_execute(req,'create_company',null,null,null,jsonb_build_object('name',name,'first_branch','الفرع الرئيسي','logo_url',''));
 same:=public.dlv_owner_assistant_execute(req,'create_company',null,null,null,jsonb_build_object('name',name,'first_branch','الفرع الرئيسي','logo_url',''));
 IF same<>answer THEN RAISE EXCEPTION 'Idempotent retry failed';END IF;
 cid:=(answer->>'company_id')::bigint;bid:=(answer->>'branch_id')::int;
 BEGIN PERFORM public.dlv_owner_assistant_execute(req,'create_company',null,null,null,jsonb_build_object('name',name||' آخر'));RAISE EXCEPTION 'Reused request accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 BEGIN PERFORM public.dlv_owner_assistant_execute(gen_random_uuid(),'create_company',null,null,null,jsonb_build_object('name',name));RAISE EXCEPTION 'Duplicate company accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 same:=public.dlv_owner_assistant_execute(gen_random_uuid(),'add_branch',cid,null,null,jsonb_build_object('name','فرع ثان'));
 same:=public.dlv_owner_assistant_execute(gen_random_uuid(),'rename_branch',cid,bid,null,jsonb_build_object('name','اسم فرع معدل','expected_name','الفرع الرئيسي'));
 BEGIN PERFORM public.dlv_owner_assistant_execute(gen_random_uuid(),'rename_branch',cid,bid,null,jsonb_build_object('name','اسم متأخر','expected_name','الفرع الرئيسي'));RAISE EXCEPTION 'Stale branch accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
 EXECUTE 'RESET ROLE';
 IF NOT EXISTS(SELECT 1 FROM public.dlv_companies WHERE id=cid AND onboarding_status='pending_isolation') OR NOT EXISTS(SELECT 1 FROM public.dlv_branches WHERE id=bid AND company_id=cid AND NOT active) OR NOT EXISTS(SELECT 1 FROM public.dlv_company_branding WHERE company_id=cid AND brand_name=name) THEN RAISE EXCEPTION 'Company isolation default failed';END IF;
 SELECT * INTO STRICT e FROM public.dlv_profiles WHERE active AND role<>'admin' AND coalesce(workflow_role,'')<>'admin' LIMIT 1;
 SELECT company_id INTO ecid FROM public.dlv_branches WHERE id=e.branch_id;
 EXECUTE 'SET LOCAL ROLE authenticated';
 ctx:=public.dlv_owner_assistant_context(ecid,e.branch_id);
 SELECT x INTO STRICT item FROM jsonb_array_elements(ctx->'employees')x WHERE x->>'user_id'=e.user_id::text;
 BEGIN PERFORM public.dlv_owner_assistant_execute(gen_random_uuid(),'update_employee',cid,e.branch_id,e.user_id,jsonb_build_object('full_name',e.full_name,'employee_code',e.employee_code,'phone','','version',item->>'version'));RAISE EXCEPTION 'Cross company update accepted';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 same:=public.dlv_owner_assistant_execute(gen_random_uuid(),'update_employee',ecid,e.branch_id,e.user_id,jsonb_build_object('full_name','اسم اختبار المساعد','employee_code',e.employee_code,'phone','','version',item->>'version'));
 BEGIN PERFORM public.dlv_owner_assistant_execute(gen_random_uuid(),'update_employee',ecid,e.branch_id,e.user_id,jsonb_build_object('full_name','اسم قديم','employee_code',e.employee_code,'phone','','version',item->>'version'));RAISE EXCEPTION 'Stale account accepted';EXCEPTION WHEN serialization_failure THEN NULL;END;
 BEGIN PERFORM public.dlv_owner_assistant_execute(gen_random_uuid(),'update_employee',ecid,e.branch_id,e.user_id,'{"role":"admin"}');RAISE EXCEPTION 'Role injection accepted';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 IF jsonb_array_length(public.dlv_owner_assistant_history())<4 THEN RAISE EXCEPTION 'History missing';END IF;
 EXECUTE 'RESET ROLE';
 IF NOT EXISTS(SELECT 1 FROM public.dlv_profiles WHERE user_id=e.user_id AND role=e.role AND workflow_role IS NOT DISTINCT FROM e.workflow_role AND branch_id=e.branch_id) THEN RAISE EXCEPTION 'Unrequested permissions change';END IF;
 INSERT INTO auth.sessions(id,user_id,created_at,updated_at) VALUES(gen_random_uuid(),e.user_id,now(),now()) RETURNING id INTO sid;
 PERFORM set_config('request.jwt.claim.sub',e.user_id::text,true);PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',e.user_id,'session_id',sid,'exp',extract(epoch from now()+interval '1 hour')::bigint,'aal','aal1')::text,true);
 EXECUTE 'SET LOCAL ROLE authenticated';
 BEGIN PERFORM public.dlv_owner_assistant_context(ecid,e.branch_id);RAISE EXCEPTION 'Employee read context';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.dlv_owner_assistant_history();RAISE EXCEPTION 'Employee read history';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 BEGIN PERFORM public.dlv_owner_assistant_execute(gen_random_uuid(),'add_branch',ecid,null,null,'{"name":"غير مصرح"}');RAISE EXCEPTION 'Employee executed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';EXECUTE 'SET LOCAL ROLE anon';
 BEGIN PERFORM public.dlv_owner_assistant_history();RAISE EXCEPTION 'Anonymous read history';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 EXECUTE 'RESET ROLE';
 INSERT INTO assistant_checks VALUES('owner_lock_required_and_employee_anon_denied',true),('four_supported_actions_work',true),('company_brand_first_branch_atomic_and_pending',true),('duplicate_retry_does_not_duplicate_records',true),('invalid_logo_unknown_action_and_role_payload_denied',true),('company_branch_user_scope_enforced',true),('stale_account_and_branch_previews_denied',true),('roles_and_branch_membership_preserved',true),('execution_history_recorded',true);
END $qa$;
SELECT * FROM assistant_checks;
ROLLBACK;